function factory(type) {
  const base = { id: uid(), type, align: "left", assignee: "system" };
  switch (type) {
    case "columns": return { ...base, count: 2, cols: [[], []] };
    case "logo": return { ...base, size: "md", url: "", assignee: "system" };
    case "title": return { ...base, text: "Untitled template", assignee: "system" };
    case "subtitle": return { ...base, text: "Add a short subtitle", assignee: "system" };
    case "text": return { ...base, content: "Type your text here.", locked: false, source: "default", assignee: "system" };
    case "tickbox": return { ...base, question: "Confirm this statement?", checked: false, source: "installer", assignee: "installer" };
    case "signature": return { ...base, signer: "customer", role: "technical_op", label: "", dateMode: "today", dateFixed: "", dateField: "commissioning_date", assignee: "customer" };
    case "datestamp": return { ...base, label: "Date", mode: "auto", fixed: "", assignee: "system" };
    case "linked": return { ...base, field: "customer_name", assignee: "system" };
    case "labeled": return { ...base, label: "Issued By:", field: "designer_name", assignee: "system" };
    case "labeledDate": return { ...base, label: "Date:", dateMode: "today", dateFixed: "", dateField: "commissioning_date", assignee: "system" };
    case "table": {
      const grid = makeSpecTableGrid();
      return { ...base, rows: grid.length, cols: 3, width: "full", colW: [1, 1, 1], grid, assignee: "system" };
    }
    default: return base;
  }
}
function resolveAssignee(blk) {
  if (blk.assignee) return blk.assignee;
  if (blk.type === "signature") return blk.signer === "customer" ? "customer" : "installer";
  if (blk.type === "tickbox") return blk.source === "installer" ? "installer" : "system";
  if (blk.type === "text") return blk.source === "installer" ? "installer" : "system";
  return "system";
}

